// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.vision.infrastructureimport timber.log.Timberimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.delayimport kotlinx.coroutines.flow.MutableStateFlowimport kotlinx.coroutines.flow.StateFlowimport kotlinx.coroutines.flow.asStateFlowimport kotlinx.coroutines.withContext/** * NOUS — Sensor Duty Cycling Controller (Module 6 v4 — Step 6.7, CRITICAL). * * Implements **Sensor Duty Cycling** to push battery life from 5.5 hours → 6-7 * hours on static scenes, per strategy v4 §"Critical Engineering Fix 2: Camera * Sensor Baseline Power Drain". * * ## Why this matters * * Motion Gating (Step 6.3) saves NPU/CPU cycles but the Camera2 API stream must * remain open to detect motion — meaning the physical camera sensor + hardware * ISP are constantly powered on, pulling 150-200 mA baseline. * * Sensor Duty Cycling closes the camera during static scenes and uses the * **accelerometer** (5 mA) to detect when the user moves the phone. When * motion is detected, the camera reopens (200 ms wake latency). * * ## Duty Cycle (per strategy v4 §"Sensor Duty Cycling") * * ``` * Phase 1: Active Monitoring (sensor ON, 5 FPS capture for motion detection) *   - Duration: 2 seconds *   - Power: 175 mA (sensor + ISP) + 30 mA (motion diff) = 205 mA *   - If motion detected → enter Phase 2 (full inference) *   - If no motion → enter Phase 2-sleep * * Phase 2-sleep: Sensor Standby (sensor OFF, accelerometer-based wake) *   - Duration: 8 seconds *   - Power: 0 mA (sensor off) + 5 mA (accelerometer poll) = 5 mA *   - Accelerometer detects device movement → wake sensor → Phase 1 *   - If no accelerometer event → stay in Phase 2-sleep * * Result: 10-second cycle = 2s active (205 mA) + 8s standby (5 mA) *   Average power: (2×205 + 8×5) / 10 = 45 mA (vs 205 mA continuous) *   → Static scene battery: 5 hrs → 6-7 hrs * ``` * * ## Auto-Disable * * When rapid motion is detected (>40% pixel diff), duty cycling is automatically * disabled for 30 seconds to ensure smooth real-time inference. Re-enabled when * the scene stabilizes. * * ## User Feedback * * When duty cycling is active, the user hears: * > "Vision is in power-saving mode. Point at something and I'll wake up." * * ## Testability * * [AccelerometerProbe] abstracts Android's SensorManager. Tests inject * [FakeAccelerometerProbe] to simulate motion events. * * @see <a href="docs/strategy/module-6-vision-strategy-v4.md">§Critical Engineering Fix 2: Sensor Duty Cycling</a> */class SensorDutyCyclingController(    private val accelerometerProbe: AccelerometerProbe,    private val activePhaseMs: Long = DEFAULT_ACTIVE_PHASE_MS,    private val standbyPhaseMs: Long = DEFAULT_STANDBY_PHASE_MS,    private val rapidMotionCooldownMs: Long = DEFAULT_RAPID_MOTION_COOLDOWN_MS,    private val motionThreshold: Float = DEFAULT_MOTION_THRESHOLD,) {    private val _dutyCycleState = MutableStateFlow(DutyCycleState.ACTIVE)    val dutyCycleState: StateFlow<DutyCycleState> = _dutyCycleState.asStateFlow()    /** True if duty cycling is currently enabled (disabled during rapid motion). */    @Volatile    private var dutyCyclingEnabled: Boolean = true    /** Timestamp when rapid-motion cooldown expires (0 = no cooldown active). */    @Volatile    private var rapidMotionCooldownEndMs: Long = 0L    /** Total duty cycles completed (for stats). */    @Volatile    private var totalCyclesCompleted: Int = 0    /** Total time spent in standby phase (for battery savings calculation). */    @Volatile    private var totalStandbyTimeMs: Long = 0L    /**     * Run the duty cycling loop.     *     * Alternates between ACTIVE (camera on, motion detection) and STANDBY     * (camera off, accelerometer wake) phases.     *     * @param onMotionDetected callback when motion is detected (camera should reopen for inference).     * @param shouldContinue returns false to stop the loop.     */    suspend fun runDutyCycle(        dispatcher: CoroutineDispatcher,        onMotionDetected: suspend () -> Unit,        shouldContinue: () -> Boolean,    ) = withContext(dispatcher) {        Timber.tag(TAG).i("Sensor duty cycling started (active=${activePhaseMs}ms, standby=${standbyPhaseMs}ms).")        while (shouldContinue()) {            // Check if rapid-motion cooldown is active (duty cycling disabled).            val now = System.currentTimeMillis()            if (now < rapidMotionCooldownEndMs) {                _dutyCycleState.value = DutyCycleState.DISABLED_RAPID_MOTION                delay(RAPID_MOTION_POLL_MS)                continue            }            // Phase 1: Active monitoring.            _dutyCycleState.value = DutyCycleState.ACTIVE            val activeStart = System.currentTimeMillis()            // During active phase, the camera is on + motion gating runs.            // The caller (ObjectDetectionEngine) handles motion detection.            // We just wait for the active phase duration.            delay(activePhaseMs)            // Check if motion was detected during active phase.            // (The caller signals this via [signalMotionDetected].)            if (motionDetectedDuringActivePhase) {                motionDetectedDuringActivePhase = false                // Skip standby — go directly to next active phase.                continue            }            // Phase 2: Standby (camera off, accelerometer wake).            if (dutyCyclingEnabled) {                _dutyCycleState.value = DutyCycleState.STANDBY                val standbyStart = System.currentTimeMillis()                // Wait for accelerometer motion OR standby duration to elapse.                val standbyEnd = standbyStart + standbyPhaseMs                while (System.currentTimeMillis() < standbyEnd) {                    if (accelerometerProbe.detectMotion(motionThreshold)) {                        Timber.tag(TAG).d("Accelerometer woke sensor early (motion detected).")                        break                    }                    delay(ACCELEROMETER_POLL_MS)                }                totalStandbyTimeMs += System.currentTimeMillis() - standbyStart            }            totalCyclesCompleted++        }        Timber.tag(TAG).i("Sensor duty cycling stopped (cycles=$totalCyclesCompleted, standby=${totalStandbyTimeMs}ms).")    }    /** Flag set by caller when motion is detected during active phase. */    @Volatile    private var motionDetectedDuringActivePhase: Boolean = false    /**     * Signal that motion was detected during the active phase.     *     * Called by [com.roshan.persona.vision.detection.ObjectDetectionEngine]     * when MotionGatingController reports non-STATIC motion.     */    fun signalMotionDetected() {        motionDetectedDuringActivePhase = true    }    /**     * Signal that rapid motion was detected (disables duty cycling for cooldown).     *     * Called by [com.roshan.persona.vision.detection.ObjectDetectionEngine]     * when MotionState.RAPID is detected.     */    fun signalRapidMotion() {        rapidMotionCooldownEndMs = System.currentTimeMillis() + rapidMotionCooldownMs        dutyCyclingEnabled = true  // Will re-enable after cooldown        Timber.tag(TAG).i("Rapid motion detected — duty cycling disabled for ${rapidMotionCooldownMs}ms.")    }    /**     * Manually enable/disable duty cycling (user can disable in Settings).     */    fun setEnabled(enabled: Boolean) {        dutyCyclingEnabled = enabled        Timber.tag(TAG).i("Duty cycling ${if (enabled) "enabled" else "disabled"} by user.")    }    /** True if duty cycling is currently enabled. */    fun isEnabled(): Boolean = dutyCyclingEnabled    /** Get the current duty cycle state. */    fun getCurrentState(): DutyCycleState = _dutyCycleState.value    /** Get stats (for Settings UI + battery savings calculation). */    fun stats(): DutyCycleStats = DutyCycleStats(        totalCyclesCompleted = totalCyclesCompleted,        totalStandbyTimeMs = totalStandbyTimeMs,        currentDutyCycleState = _dutyCycleState.value,        dutyCyclingEnabled = dutyCyclingEnabled,        rapidMotionCooldownActive = System.currentTimeMillis() < rapidMotionCooldownEndMs,        estimatedBatterySavingsPercent = computeBatterySavingsPercent(),    )    /**     * Compute estimated battery savings (%).     *     * Without duty cycling: 100% active = 205 mA average.     * With duty cycling: (2s × 205 + 8s × 5) / 10s = 45 mA average.     * Savings = (205 - 45) / 205 = 78%.     */    private fun computeBatterySavingsPercent(): Float {        if (totalCyclesCompleted == 0) return 0f        val totalCycleTimeMs = totalCyclesCompleted.toLong() * (activePhaseMs + standbyPhaseMs)        if (totalCycleTimeMs == 0L) return 0f        val standbyFraction = totalStandbyTimeMs.toFloat() / totalCycleTimeMs        // Savings = standbyFraction × (205-5)/205 = standbyFraction × 0.976        return standbyFraction * 97.6f    }    private companion object {        private const val TAG = "SensorDutyCycle"        private const val DEFAULT_ACTIVE_PHASE_MS = 2000L  // 2 seconds        private const val DEFAULT_STANDBY_PHASE_MS = 8000L  // 8 seconds        private const val DEFAULT_RAPID_MOTION_COOLDOWN_MS = 30_000L  // 30 seconds        private const val DEFAULT_MOTION_THRESHOLD = 1.5f  // m/s² acceleration change        private const val ACCELEROMETER_POLL_MS = 500L  // Poll accelerometer every 500ms during standby        private const val RAPID_MOTION_POLL_MS = 1000L  // Poll every 1s during cooldown    }}// ──────────────────────────────────────────────────────────────────────────/** Duty cycle state. */enum class DutyCycleState(val displayName: String) {    /** Camera ON, motion detection active (5 FPS). */    ACTIVE("Active (Camera On)"),    /** Camera OFF, accelerometer wake (5 mA). */    STANDBY("Standby (Power Saving)"),    /** Duty cycling disabled due to rapid motion (30s cooldown). */    DISABLED_RAPID_MOTION("Disabled (Rapid Motion Cooldown)"),}/** Stats for Settings UI. */data class DutyCycleStats(    val totalCyclesCompleted: Int,    val totalStandbyTimeMs: Long,    val currentDutyCycleState: DutyCycleState,    val dutyCyclingEnabled: Boolean,    val rapidMotionCooldownActive: Boolean,    val estimatedBatterySavingsPercent: Float,)// ──────────────────────────────────────────────────────────────────────────/** * Accelerometer probe interface — abstracts Android SensorManager. * * Production: [AndroidAccelerometerProbe] wraps SensorManager.SENSOR_DELAY_NORMAL. * Tests: [FakeAccelerometerProbe] returns canned motion events. */interface AccelerometerProbe {    /**     * Check if significant motion was detected since the last call.     *     * @param threshold acceleration change threshold (m/s²).     * @return true if motion exceeds threshold.     */    fun detectMotion(threshold: Float): Boolean}
